// main.ts
async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  // BUG: guard is newed by hand → outside DI → reflector + users are not the real providers
  app.useGlobalGuards(new RolesGuard(new Reflector(), null as any));
  await app.listen(3000);
}

// rolesguard.ts
@Injectable()
export class RolesGuard implements CanActivate {
  constructor(private reflector: Reflector, private users: UsersService) {}
  async canActivate(ctx: ExecutionContext) {
    const roles = this.reflector.get<string[]>('roles', ctx.getHandler());
    if (!roles) return true;
    const { user } = ctx.switchToHttp().getRequest();
    return this.users.hasAnyRole(user.id, roles);
  }
}

model.en:
// app.module.ts — bind via the APP_GUARD token so Nest builds the guard through DI
@Module({
  providers: [
    UsersService,
    { provide: APP_GUARD, useClass: RolesGuard }, // global AND dependency-injected
  ],
})
export class AppModule {}

// main.ts — drop the hand-newed registration entirely
async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  await app.listen(3000); // no app.useGlobalGuards(new RolesGuard(...))
}

Why: { provide: APP_GUARD, useClass: RolesGuard } registers the guard as a real provider, so Nest instantiates it through the container and injects the real Reflector and UsersService (and whatever UsersService itself depends on) — while still applying it to every route. The hand-newed version lived outside DI, so its constructor args were whatever you passed (a fresh Reflector and a null service), which is why the role check threw and the surrounding handling defaulted open. useGlobalGuards is only acceptable for a dependency-free guard; anything that injects must use the APP_GUARD token (APP_INTERCEPTOR / APP_PIPE / APP_FILTER for the other kinds).

model.ru:
// app.module.ts — биндим через токен APP_GUARD, чтобы Nest построил guard через DI
@Module({
  providers: [
    UsersService,
    { provide: APP_GUARD, useClass: RolesGuard }, // глобально И с инъекцией зависимостей
  ],
})
export class AppModule {}

// main.ts — полностью убираем созданную руками регистрацию
async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  await app.listen(3000); // нет app.useGlobalGuards(new RolesGuard(...))
}

Почему: { provide: APP_GUARD, useClass: RolesGuard } регистрирует guard как настоящий провайдер, так что Nest инстанцирует его через контейнер и инжектит реальные Reflector и UsersService (и всё, от чего сам UsersService зависит) — при этом он по-прежнему применяется к каждому маршруту. Версия с ручным new жила вне DI, поэтому её аргументы конструктора были тем, что ты передал (свежий Reflector и null-сервис), из-за чего проверка роли выбрасывала, а окружающая обработка по умолчанию открывала доступ. useGlobalGuards приемлем только для guard без зависимостей; всё, что инжектит, обязано использовать токен APP_GUARD (APP_INTERCEPTOR / APP_PIPE / APP_FILTER для остальных видов).
